/** Three months of invoices per paying tenant. */
const invoices: Invoice[] = [];
let invoiceSeq = 1040;
for (const client of clients) {
	if (client.status === "trial") continue;
	const plan = plans.find((p) => p.id === client.planId)!;
	const yearly = client.billingCycle === "yearly";
	const periods = yearly ? [140] : [100, 70, 40, 10];
	periods.forEach((startAgo, i) => {
		const subtotal = yearly ? plan.priceYearly : plan.priceMonthly;
		const tax = Math.round(subtotal * 0.08 * 100) / 100;
		const last = i === periods.length - 1;
		const overdue = client.status === "past_due" && last;
		invoiceSeq += 1;
		invoices.push({
			id: `inv_${invoiceSeq}`,
			number: `INV-${invoiceSeq}`,
			clientId: client.id,
			currency: plan.currency,
			lines: [{ description: `${plan.name} plan — ${yearly ? "yearly" : "monthly"}`, amount: subtotal }],
			subtotal,
			discount: 0,
			tax,
			total: subtotal + tax,
			status: overdue ? "overdue" : "paid",
			issuedAt: ago(startAgo),
			dueAt: ago(startAgo - 14),
			paidAt: overdue ? undefined : ago(startAgo - 2),
			periodStart: ago(startAgo),
			periodEnd: ago(startAgo - (yearly ? 365 : 30)),
		});
	});
}

